import{_ as e,o as t,c as i,a2 as a}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Rate-Based Detection","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/detection-engine/rate-based.md","filePath":"openshield-xdp/detection-engine/rate-based.md","lastUpdated":1782568991000}'),n={name:"openshield-xdp/detection-engine/rate-based.md"};function d(h,s,l,p,o,r){return t(),i("div",null,[...s[0]||(s[0]=[a(`<h1 id="rate-based-detection" tabindex="-1">Rate-Based Detection <a class="header-anchor" href="#rate-based-detection" aria-label="Permalink to &quot;Rate-Based Detection&quot;">​</a></h1><p>Per-IP, per-second rate thresholds with <strong>additive suspicion scoring</strong>. When an IP exceeds a threshold, points are added to its <code>suspicion_score</code>. When the cumulative score reaches the effective ban threshold, the IP is banned.</p><h2 id="how-scoring-works" tabindex="-1">How scoring works <a class="header-anchor" href="#how-scoring-works" aria-label="Permalink to &quot;How scoring works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Window (1 second):</span></span>
<span class="line"><span>  IP sends N packets, M bytes, T TCP, U UDP, I ICMP, S SYN</span></span>
<span class="line"><span>  For each threshold exceeded → add score to suspicion_score</span></span>
<span class="line"><span>  suspicion_score decays by suspicion_threshold/10 each window</span></span>
<span class="line"><span>  When suspicion_score ≥ effective_threshold → ban</span></span></code></pre></div><h2 id="thresholds-and-scores" tabindex="-1">Thresholds and scores <a class="header-anchor" href="#thresholds-and-scores" aria-label="Permalink to &quot;Thresholds and scores&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Default threshold</th><th>Default score</th><th>Config field</th></tr></thead><tbody><tr><td>Packets/s</td><td>850</td><td>20</td><td><code>pps_threshold</code> / <code>pps_score</code></td></tr><tr><td>Bytes/s</td><td>8,912,896 (~8.5 MB/s)</td><td>20</td><td><code>bps_threshold</code> / <code>bps_score</code></td></tr><tr><td>TCP/s</td><td>680</td><td>15</td><td><code>tcp_pps_threshold</code> / <code>tcp_pps_score</code></td></tr><tr><td>UDP/s</td><td>425</td><td>15</td><td><code>udp_pps_threshold</code> / <code>udp_pps_score</code></td></tr><tr><td>ICMP/s</td><td>85</td><td>25</td><td><code>icmp_pps_threshold</code> / <code>icmp_pps_score</code></td></tr><tr><td>SYN/s</td><td>170</td><td>30</td><td><code>syn_pps_threshold</code> / <code>syn_pps_score</code></td></tr></tbody></table><p>SYN floods are scored higher by default (30 points vs 20 for PPS) because they are almost always malicious at high rates.</p><h2 id="check-frequency" tabindex="-1">Check frequency <a class="header-anchor" href="#check-frequency" aria-label="Permalink to &quot;Check frequency&quot;">​</a></h2><p>Threshold scoring evaluates on two triggers:</p><ol><li><strong>Window reset</strong> — every 1 second, the per-IP window counters become the rate</li><li><strong>Per-packet sampling</strong> — every 256th packet (<code>pkt_count &amp; 0xFF == 0</code>) triggers a mid-window evaluation</li></ol><p>This catches rate violations within ~256 packets instead of waiting the full second.</p><h2 id="suspicion-decay" tabindex="-1">Suspicion decay <a class="header-anchor" href="#suspicion-decay" aria-label="Permalink to &quot;Suspicion decay&quot;">​</a></h2><p>Suspicion score uses <strong>subtractive decay</strong> — a fixed amount is subtracted each window reset:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">decay_amount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> suspicion_threshold </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // default: 100/10 = 10</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (decay_amount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) decay_amount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // floor of 5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stats</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">suspicion_score </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> decay_amount;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // never goes below 0</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Config value</th><th>Decay amount</th><th>Time to clear a 100-point burst</th></tr></thead><tbody><tr><td>100</td><td>10</td><td>10 windows (10s)</td></tr><tr><td>200</td><td>20</td><td>5 windows (5s)</td></tr><tr><td>50</td><td>5 (floor)</td><td>20 windows (20s)</td></tr></tbody></table><p>The <code>suspicion_decay_percent</code> config field controls the <em>decay amount</em> indirectly: <code>decay_percent &gt;= 100</code> disables decay entirely. Otherwise the subtractive formula above applies.</p><div class="warning custom-block"><p class="custom-block-title">Subtractive, not multiplicative</p><p>The old documentation described multiplicative decay (<code>score * 0.5</code>). The actual implementation is subtractive. This is deliberate — subtractive decay prevents a single massive burst from keeping the score permanently elevated.</p></div><h2 id="repeat-offenders" tabindex="-1">Repeat offenders <a class="header-anchor" href="#repeat-offenders" aria-label="Permalink to &quot;Repeat offenders&quot;">​</a></h2><p>The effective ban threshold tightens for repeat offenders:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>effective_threshold = suspicion_threshold * 2 / (2 + ban_count)</span></span>
<span class="line"><span>minimum floor = 10</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Ban count</th><th>Effective threshold (default 100)</th></tr></thead><tbody><tr><td>0 (first offense)</td><td>100</td></tr><tr><td>1</td><td>66</td></tr><tr><td>2</td><td>50</td></tr><tr><td>3</td><td>40</td></tr><tr><td>5</td><td>28</td></tr><tr><td>10+</td><td>10 (floor)</td></tr></tbody></table><p>The <code>ban_count</code> is stored per-IP in <code>ip_stats</code> and is never reset by the kernel. It is cleared only by userspace restart (all <code>ip_stats</code> maps are cleared on loader startup).</p><h2 id="attack-mode-threshold-tightening" tabindex="-1">Attack mode threshold tightening <a class="header-anchor" href="#attack-mode-threshold-tightening" aria-label="Permalink to &quot;Attack mode threshold tightening&quot;">​</a></h2><p>When the dynamic mitigation subsystem declares <code>ATTACK_UNDER_ATTACK</code>, all rate thresholds are multiplied by <code>attack_threshold_multiplier_percent</code> (default 50%):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>During attack: pps_threshold = 850 * 0.5  = 425</span></span>
<span class="line"><span>               bps_threshold = 8912896 * 0.5 = 4456448</span></span>
<span class="line"><span>               ...etc.</span></span></code></pre></div><p>This makes detection more aggressive during confirmed attack conditions and returns to normal thresholds when the attack subsides.</p><h2 id="token-bucket-alternative" tabindex="-1">Token bucket alternative <a class="header-anchor" href="#token-bucket-alternative" aria-label="Permalink to &quot;Token bucket alternative&quot;">​</a></h2><p>Set <code>rate_limit_mode: token_bucket</code> to use token bucket rate limiting instead of threshold scoring:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rate_limit_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">token_bucket</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  token_rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Tokens refilled per second per IP</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  token_burst</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Max tokens before draining</span></span></code></pre></div><p>Tokens refill proportionally to elapsed nanoseconds. First packet seeds the bucket. Each packet drains 1 token. Drop when empty. The token bucket is independent of suspicion scoring — no ban is triggered on token bucket exhaustion; packets are simply dropped.</p><div class="tip custom-block"><p class="custom-block-title">Which mode to choose</p><ul><li><strong>Threshold scoring</strong>: Best for servers with mixed traffic profiles. Allows brief bursts (decay clears them), bans persistent offenders.</li><li><strong>Token bucket</strong>: Best for strict rate limiting of known-good traffic patterns. Predictable, no stateful ban tracking.</li></ul></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">850</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  bps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8912896</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tcp_pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">680</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  udp_pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">425</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  icmp_pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">85</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  syn_pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">170</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  suspicion_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ban_duration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  suspicion_decay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.5&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # Actually subtractive (see above)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rate_limit_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">threshold</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  token_rate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # Set &gt;0 for token bucket mode</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  token_burst</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # Set &gt;0 for token bucket mode</span></span></code></pre></div><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/mitigation/bans">Ban System</a> · <a href="/pingless-studios-docs/openshield-xdp/mitigation/rate-limiting">Rate Limiting</a> · <a href="/pingless-studios-docs/openshield-xdp/mitigation/overview">Mitigation Overview</a></p>`,35)])])}const g=e(n,[["render",d]]);export{k as __pageData,g as default};
